import{_ as e,o as a,c as r,a5 as d}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"Listening Evidence Card: From Playback Time to Meaning Reconstruction","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/listening-audit.en.md","filePath":"public/downloads/worksheets/listening-audit.en.md","lastUpdated":1795488252000}'),n={name:"public/downloads/worksheets/listening-audit.en.md"};function i(o,t,s,l,c,h){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="listening-evidence-card-from-playback-time-to-meaning-reconstruction" tabindex="-1">Listening Evidence Card: From Playback Time to Meaning Reconstruction <a class="header-anchor" href="#listening-evidence-card-from-playback-time-to-meaning-reconstruction" aria-label="Permalink to &quot;Listening Evidence Card: From Playback Time to Meaning Reconstruction&quot;">​</a></h1><p>Copy this card into a private note for one main source and one parallel source at a time. Do not record passwords, client data, or unapproved meeting, student, or family audio. Preserve copyrighted clips, transcripts, and notes only within permitted personal-learning use.</p><h2 id="_1-define-the-task-and-real-world-boundary" tabindex="-1">1. Define the Task and Real-World Boundary <a class="header-anchor" href="#_1-define-the-task-and-real-world-boundary" aria-label="Permalink to &quot;1. Define the Task and Real-World Boundary&quot;">​</a></h2><h3 id="listening-evidence-yyyy-mm-dd" tabindex="-1">Listening Evidence - YYYY-MM-DD <a class="header-anchor" href="#listening-evidence-yyyy-mm-dd" aria-label="Permalink to &quot;Listening Evidence - YYYY-MM-DD&quot;">​</a></h3><p>Real situation:<br> Task: gist / detail / relationship / action / interaction / transfer<br> What must I answer, decide, or do afterwards?<br> Completion standard:<br> Confirmation, captions, and written support allowed in reality:<br> Recording, upload, transcript, and sharing permission:</p><p>Training may remove scaffolds. Real work must not abandon necessary safety confirmation to prove ability.</p><h2 id="_2-audit-material-and-conditions" tabindex="-1">2. Audit Material and Conditions <a class="header-anchor" href="#_2-audit-material-and-conditions" aria-label="Permalink to &quot;2. Audit Material and Conditions&quot;">​</a></h2><p>Main-source title, origin, and access date:<br> Parallel-source title, origin, and access date:<br> Segment length:<br> Reliable English transcript: human / automatic-needs-checking / none<br> Topic, speaker, and accent familiarity:<br> Device / network / room noise:<br> Copyright and retention boundary:<br> Why I will return during the next seven days:</p><table tabindex="0"><thead><tr><th>Condition</th><th>Main source</th><th>Parallel source</th><th>Comparable?</th></tr></thead><tbody><tr><td>Task and difficulty</td><td></td><td></td><td></td></tr><tr><td>Length and information density</td><td></td><td></td><td></td></tr><tr><td>Transcript quality</td><td></td><td></td><td></td></tr><tr><td>Speaker/accent familiarity</td><td></td><td></td><td></td></tr><tr><td>Device and environment</td><td></td><td></td><td></td></tr></tbody></table><p>Different material is not automatically a comparable transfer condition. Keep the task and approximate difficulty similar.</p><h2 id="_3-preserve-a-no-caption-first-pass" tabindex="-1">3. Preserve a No-Caption First Pass <a class="header-anchor" href="#_3-preserve-a-no-caption-first-pass" aria-label="Permalink to &quot;3. Preserve a No-Caption First Pass&quot;">​</a></h2><p>First-pass permission: pause / speed / captions / notes / replay<br> One-sentence gist:<br> Three certain details:<br> Speaker stance or purpose:<br> Critical number / time / person / condition:<br> Uncertain timestamps:<br> Action I would take from what I heard:<br> First-pass answer location:</p><p>Do not overwrite the first pass after a replay or caption check. It is the comparison baseline.</p><h2 id="_4-build-the-six-layer-error-map" tabindex="-1">4. Build the Six-Layer Error Map <a class="header-anchor" href="#_4-build-the-six-layer-error-map" aria-label="Permalink to &quot;4. Build the Six-Layer Error Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Timestamp</th><th>I thought I heard</th><th>Reliable content</th><th>Barrier layer</th><th>Task impact</th><th>This cycle&#39;s action</th></tr></thead><tbody><tr><td></td><td></td><td></td><td>technical / unknown language / known-not-heard / structure-reference / background-inference / attention-capacity</td><td>meaning-changing / task-blocking / recurring / effortful / low-impact</td><td></td></tr></tbody></table><p>One to three problems that most affect the task:<br> Low-impact missing words I will not repair yet:<br> Device or fatigue effects that cannot be assigned directly to ability:</p><h2 id="_5-use-the-scaffold-ladder" tabindex="-1">5. Use the Scaffold Ladder <a class="header-anchor" href="#_5-use-the-scaffold-ladder" aria-label="Permalink to &quot;5. Use the Scaffold Ladder&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Action</th><th>What became visible?</th><th>What remains unproven?</th></tr></thead><tbody><tr><td>1</td><td>First pass without captions</td><td></td><td></td></tr><tr><td>2</td><td>Replay only the 5-20 second problem segment</td><td></td><td></td></tr><tr><td>3</td><td>Open the English transcript for boundaries and structure</td><td></td><td></td></tr><tr><td>4</td><td>Check minimum definition, background, or translation</td><td></td><td></td></tr><tr><td>5</td><td>Close the text and listen at normal speed</td><td></td><td></td></tr><tr><td>6</td><td>Remove old support and retest on parallel material after 3-7 days</td><td></td><td></td></tr></tbody></table><p>Automatic-caption errors:<br> What translation helped:<br> Meaning still triggered after the text closed:<br> Segment understood only while captions remained visible:</p><h2 id="_6-make-each-pass-produce-different-evidence" tabindex="-1">6. Make Each Pass Produce Different Evidence <a class="header-anchor" href="#_6-make-each-pass-produce-different-evidence" aria-label="Permalink to &quot;6. Make Each Pass Produce Different Evidence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pass</th><th>Question</th><th>Output</th><th>Result</th></tr></thead><tbody><tr><td>1</td><td>What did I predict and recover?</td><td>Raw gist and details</td><td></td></tr><tr><td>2</td><td>Where did the difference occur?</td><td>Timestamp and barrier layer</td><td></td></tr><tr><td>3</td><td>What did minimum support explain?</td><td>Mishearing, transcript, and cause</td><td></td></tr><tr><td>4</td><td>Does sound trigger meaning after support closes?</td><td>No-text replay</td><td></td></tr><tr><td>5</td><td>How can I reconstruct and act?</td><td>Retelling / process / decision / handover</td><td></td></tr></tbody></table><p>Play count is not a result. Each pass should create a new judgment or show that repetition should stop.</p><h2 id="_7-move-from-dictation-and-shadowing-into-generation" tabindex="-1">7. Move from Dictation and Shadowing into Generation <a class="header-anchor" href="#_7-move-from-dictation-and-shadowing-into-generation" aria-label="Permalink to &quot;7. Move from Dictation and Shadowing into Generation&quot;">​</a></h2><p>High-impact 5-20 second segment:<br> My dictation:<br> Reliable transcript:<br> Boundary / ending / reduction / stress difference:<br> Delayed-shadow recording:<br> Three keywords:<br> Retelling after closing the text:<br> Explanation after changing one fact or position:<br> Unfamiliar follow-up and answer:</p><p>When shadowing is smooth and retelling is empty, shorten imitation and increase keyword reconstruction. When every word is written correctly but the gist is missing, return to structure and relationship.</p><h2 id="_8-record-ai-teacher-and-real-task-feedback" tabindex="-1">8. Record AI, Teacher, and Real-Task Feedback <a class="header-anchor" href="#_8-record-ai-teacher-and-real-task-feedback" aria-label="Permalink to &quot;8. Record AI, Teacher, and Real-Task Feedback&quot;">​</a></h2><p>Tool / reviewer / model version and date:<br> Did it use raw audio, automatic transcript, or my candidate transcript?<br> Error category it proposed:<br> Did it invent wording, background, or speaker intention?<br> Teacher/peer check:<br> Response, action, or repair result in the real task:<br> What I accepted / rejected, and why:</p><p>AI and automatic transcripts provide candidates, not final judgment about the original sound.</p><h2 id="_9-test-delayed-retention-and-transfer" tabindex="-1">9. Test Delayed Retention and Transfer <a class="header-anchor" href="#_9-test-delayed-retention-and-transfer" aria-label="Permalink to &quot;9. Test Delayed Retention and Transfer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>What is removed</th><th>Changed condition</th><th>Output</th><th>Result</th></tr></thead><tbody><tr><td>Day 1</td><td>No full captions</td><td>Main source</td><td>First pass and meaning reconstruction</td><td></td></tr><tr><td>Days 3-7</td><td>Old notes and transcript removed</td><td>Parallel source</td><td>Gist, detail, and action</td><td></td></tr><tr><td>Day 14</td><td>Recent feedback removed</td><td>New speaker, accent, or device</td><td>Retelling plus unfamiliar follow-up</td><td></td></tr><tr><td>Day 30</td><td>All practice prompts closed</td><td>Real meeting, course, or conversation</td><td>Complete task</td><td></td></tr></tbody></table><p>Method still available after seven days:<br> Barrier that returned after material changed:<br> Did full-caption or translation dependence decrease?<br> Can I request repetition, confirm, and preserve agreement more reliably?<br> One variable for the next cycle:</p><h2 id="_10-score-and-decide" tabindex="-1">10. Score and Decide <a class="header-anchor" href="#_10-score-and-decide" aria-label="Permalink to &quot;10. Score and Decide&quot;">​</a></h2><p>Score 0-2: <code>0=not completed</code>, <code>1=prompt-dependent or unstable</code>, <code>2=completed under the current condition</code>.</p><table tabindex="0"><thead><tr><th>Item</th><th style="text-align:right;">Day 1</th><th style="text-align:right;">Day 7</th><th style="text-align:right;">Day 14</th><th>Evidence reason</th></tr></thead><tbody><tr><td>Preserve the first-pass main line</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Recover critical details and relationships</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Locate the barrier layer</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Understand after captions close</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Reconstruct, respond, or act</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Complete after material, speaker, or device changes</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><p>Current evidence supports: continue main source / downgrade to extensive listening / replace source / move to another problem<br> Most important evidence:<br> Conclusion I still cannot draw:<br> Smallest next task:<br> Next review date:</p><p>Related chapters: <a href="https://byoungd.github.io/up/en/threads/part-1/3-listening" target="_blank" rel="noreferrer">Listening: From Sound Recognition to Real Understanding</a> | <a href="https://byoungd.github.io/up/en/threads/part-1/5-speaking" target="_blank" rel="noreferrer">Speaking</a> | <a href="https://byoungd.github.io/up/en/threads/part-1/7-ai" target="_blank" rel="noreferrer">Learning English with AI</a> | <a href="https://byoungd.github.io/up/en/templates/evidence-chain" target="_blank" rel="noreferrer">Evidence Chain Template</a></p><hr><p>Source: <a href="https://byoungd.github.io/up/en/templates/listening-audit" target="_blank" rel="noreferrer">Still Here</a> · Manuscript updated: 2026-09-02. Content: <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>.</p>',38)])])}const b=e(n,[["render",i]]);export{u as __pageData,b as default};
